internal static Outcome DecideOutcome(
    long elapsedMs,
    long silenceMs,
    long realOutputSilenceMs,
    long subtreeIdleForMs,
    bool firstPulseReceived,
    int firstOutputTimeoutMs,
    int inactivityTimeoutMs,
    int absoluteCeilingMs,
    WedgeSample sample)
{
    // Absolute ceiling first (it wins when set).
    if (absoluteCeilingMs > 0 && elapsedMs >= absoluteCeilingMs)
        return Outcome.FiredAbsoluteCeiling;

    // First-output phase compares elapsed from start; inactivity phase compares
    // silence since the last pulse.
    var firedStall = firstPulseReceived
        ? silenceMs >= inactivityTimeoutMs
        : elapsedMs >= firstOutputTimeoutMs;
    if (firedStall)
        return Outcome.FiredStall;

    // Additive: a cpu-pulse-masked wedge (real output silent past the inactivity
    // window, agent subtree SUSTAINED-idle for the whole window, socket up).
    if (TryDecideSocketWedge(firstPulseReceived, realOutputSilenceMs, subtreeIdleForMs, inactivityTimeoutMs, sample))
        return Outcome.FiredSocketWedge;

    return Outcome.Disarmed;
}

arguments.new_string:
internal static Outcome DecideOutcome(
    long elapsedMs,
    long silenceMs,
    long realOutputSilenceMs,
    long subtreeIdleForMs,
    bool firstPulseReceived,
    int firstOutputTimeoutMs,
    int inactivityTimeoutMs,
    int absoluteCeilingMs,
    int outputSilenceTimeoutMs,
    WedgeSample sample)
{
    // Absolute ceiling first (it wins when set).
    if (absoluteCeilingMs > 0 && elapsedMs >= absoluteCeilingMs)
        return Outcome.FiredAbsoluteCeiling;

    // Output-silence ceiling (hung-LLM guard): fires when real output (stdout/
    // stderr/trace — NOT cpu pulses) has been silent beyond the per-tier limit,
    // even though cpu pulses keep the ordinary inactivity deadline masked.
    // Priority 2: below absolute ceiling, above stall and socket wedge.
    if (outputSilenceTimeoutMs > 0 && firstPulseReceived && realOutputSilenceMs >= outputSilenceTimeoutMs)
        return Outcome.FiredOutputSilence;

    // First-output phase compares elapsed from start; inactivity phase compares
    // silence since the last pulse.
    var firedStall = firstPulseReceived
        ? silenceMs >= inactivityTimeoutMs
        : elapsedMs >= firstOutputTimeoutMs;
    if (firedStall)
        return Outcome.FiredStall;

    // Additive: a cpu-pulse-masked wedge (real output silent past the inactivity
    // window, agent subtree SUSTAINED-idle for the whole window, socket up).
    if (TryDecideSocketWedge(firstPulseReceived, realOutputSilenceMs, subtreeIdleForMs, inactivityTimeoutMs, sample))
        return Outcome.FiredSocketWedge;

    return Outcome.Disarmed;
}

// For the wedge / output-silence outcomes, report real-output silence
// (≈ the inactivity window) — NOT silenceMs, which the cpu pulse keeps
// at ~one sample and which made the autopsy read like a "4s kill" —
// plus sustained-idle for wedge.
return outcome == Outcome.FiredSocketWedge
    ? new Result(outcome, lastSource, realOutputSilenceMs, subtreeIdleForMs)
    : outcome == Outcome.FiredOutputSilence
        ? new Result(outcome, lastSource, realOutputSilenceMs)
        : new Result(outcome, lastSource, silenceMs);

