// firstPulse, silenceMs, inactivityMs, subtreeIdleForMs, subtreeIdle, socket, expectWedge
[InlineData(true, 6_000, 6_000, 6_000, true, true, true)]    // exact wedge — fires
[InlineData(true, 9_999, 6_000, 9_999, true, true, true)]    // well past window — fires
[InlineData(true, 5_999, 6_000, 5_999, true, true, false)]   // silence just under window
[InlineData(true, 60_000, 6_000, 60_000, false, true, false)] // subtree BUSY now — no kill
[InlineData(true, 60_000, 6_000, 60_000, true, false, false)] // no backend socket — no kill
[InlineData(false, 60_000, 6_000, 60_000, true, true, false)] // before first output — no kill
// INCIDENT shape: real-output silent + latest sample idle + socket up, BUT a CPU
// burst happened within the window (sustained-idle < window) — healthy, no kill.
[InlineData(true, 60_000, 6_000, 2_000, true, true, false)]
[InlineData(true, 60_000, 6_000, 5_999, true, true, false)]  // sustained-idle just under window
public void TryDecideSocketWedge_FiresOnlyWhenAllGatesHold(
    bool firstPulse, long silenceMs, int inactivityMs, long subtreeIdleForMs,
    bool subtreeIdle, bool socket, bool expectWedge)
{
    var decided = ActivityWatchdog.TryDecideSocketWedge(
        firstPulse, silenceMs, subtreeIdleForMs, inactivityMs,
        new ActivityWatchdog.WedgeSample(subtreeIdle, socket));

    Assert.Equal(expectWedge, decided);
}

// ── (C) Output-silence ceiling (hung-LLM guard) ─────────────────────────

/// <summary>
/// Hung-LLM shape: cpu pulses keep silenceMs low (the ordinary inactivity
/// deadline is masked), but real output has been silent past the output-silence
/// limit. The new gate fires FiredOutputSilence — NOT the inactivity stall
/// (masked) or the socket wedge (subtree not necessarily idle).
/// </summary>
[Fact]
public void DecideOutcome_FiresOutputSilence_WhenCpuPulsesMaskInactivityButRealOutputSilent()
{
    // cpu pulse resets silenceMs to 500ms, but real-output silence is 10min.
    // Output-silence limit is 5min → fires.
    Assert.Equal(
        ActivityWatchdog.Outcome.FiredOutputSilence,
        Decide(elapsedMs: 600_000, silenceMs: 500, realOutputSilenceMs: 600_000,
            firstPulseReceived: true,
            firstOutputTimeoutMs: 90_000, inactivityTimeoutMs: 1_200_000,
            absoluteCeilingMs: 0, outputSilenceTimeoutMs: 300_000));
}

/// <summary>
/// Below the output-silence limit, the gate stays Disarmed — even though
/// real output has been silent for some time, it hasn't crossed the threshold.
/// </summary>
[Fact]
public void DecideOutcome_OutputSilence_BelowLimit_Disarmed()
{
    // Real-output silent for 4min, limit is 5min → not yet fired.
    Assert.Equal(
        ActivityWatchdog.Outcome.Disarmed,
        Decide(elapsedMs: 300_000, silenceMs: 500, realOutputSilenceMs: 240_000,
            firstPulseReceived: true,
            inactivityTimeoutMs: 1_200_000,
            outputSilenceTimeoutMs: 300_000));
}

/// <summary>
/// When outputSilenceTimeoutMs is 0 (disabled), the gate never fires even at
/// extreme real-output silence durations.
/// </summary>
[Fact]
public void DecideOutcome_OutputSilence_Disabled_DoesNotFire()
{
    // Output-silence timeout is 0 (disabled). Huge real-output silence but no fire.
    Assert.Equal(
        ActivityWatchdog.Outcome.Disarmed,
        Decide(elapsedMs: 3_600_000, silenceMs: 500, realOutputSilenceMs: 3_600_000,
            firstPulseReceived: true,
            inactivityTimeoutMs: 1_200_000,
            outputSilenceTimeoutMs: 0));
}

/// <summary>
/// Absolute ceiling wins over output-silence when both would fire
/// (priority 1 > priority 2).
/// </summary>
[Fact]
public void DecideOutcome_CeilingWinsOverOutputSilence()
{
    // Both the absolute ceiling (elapsed ≥ 5s) and output-silence (real-output
    // silent ≥ 3s with 3s limit) are met. Ceiling must win.
    Assert.Equal(
        ActivityWatchdog.Outcome.FiredAbsoluteCeiling,
        Decide(elapsedMs: 5_000, silenceMs: 500, realOutputSilenceMs: 5_000,
            firstPulseReceived: true,
            inactivityTimeoutMs: 600_000, absoluteCeilingMs: 5_000,
            outputSilenceTimeoutMs: 3_000));
}

/// <summary>
/// Output-silence wins over the ordinary inactivity stall when both would fire
/// (priority 2 > priority 3).
/// </summary>
[Fact]
public void DecideOutcome_OutputSilenceWinsOverStall()
{
    // Both the inactivity stall (silenceMs ≥ 3s) and output-silence
    // (realOutputSilenceMs ≥ 3s) are met. Output-silence must win.
    Assert.Equal(
        ActivityWatchdog.Outcome.FiredOutputSilence,
        Decide(elapsedMs: 5_000, silenceMs: 5_000, realOutputSilenceMs: 5_000,
            firstPulseReceived: true,
            inactivityTimeoutMs: 3_000, outputSilenceTimeoutMs: 3_000));
}

/// <summary>
/// Output-silence wins over socket-wedge when both would fire
/// (priority 2 > priority 4).
/// </summary>
[Fact]
public void DecideOutcome_OutputSilenceWinsOverSocketWedge()
{
    // Both the socket wedge (real-output silent + sustained-idle + socket) and
    // output-silence (real-output silent past limit) are met. Output-silence wins.
    var wedgeSample = new ActivityWatchdog.WedgeSample(SubtreeIdle: true, BackendSocketEstablished: true);
    Assert.Equal(
        ActivityWatchdog.Outcome.FiredOutputSilence,
        Decide(elapsedMs: 10_000, silenceMs: 500, realOutputSilenceMs: 10_000,
            subtreeIdleForMs: 10_000, firstPulseReceived: true,
            inactivityTimeoutMs: 3_000, outputSilenceTimeoutMs: 3_000,
            sample: wedgeSample));
}

