            ["cheap"] = 2_000,
            ["balanced"] = 120_000,
            ["frontier"] = 30_000
        },
        FirstOutputTimeoutMs = 99_000,
        InactivityTimeoutMsByTier = new Dictionary<string, int>
        {
            ["cheap"] = 3_000,
            ["balanced"] = 600_000,
            ["frontier"] = 45_000
        },
        InactivityTimeoutMs = 88_000
    };

    Assert.Equal((2_000, 3_000, 0), SwivalSubagentRunner.ResolveTierWindows(config, "cheap"));
